gsap.registerPlugin(ScrollTrigger);

type AlumniMember = {
  id: number;
  memberId: string;
  name: string;
  role?: string | null;
  batch?: string | null;
  classYear?: string | null;
  photoUrl?: string | null;
  sortOrder?: number;
};

function initials(name: string) {
  return name.split(" ").map((n) => n[0]).join("").toUpperCase().slice(0, 3);
}

export default function Alumni() {
  const rootRef = useRef<HTMLDivElement>(null);
  const { data: members = [], isLoading } = useListMembers();
  const alumni = members.filter((m: any) => m.isAlumni || m.category === "Alumni");

  const { data: page } = useQuery({
    queryKey: ["/api/page-content/alumni"],
    queryFn: () => fetchJson("/api/page-content/alumni").catch(() => null)
  });

  useEffect(() => {
    if (!rootRef.current) return;
    const ctx = gsap.context(() => {
      gsap.from(".alumni-hero .container > *", {
        opacity: 0,
        y: 30,
        duration: 0.8,
        stagger: 0.12,
        ease: "power2.out",
        delay: 0.15,
      });
    }, rootRef);
    return () => ctx.revert();
  }, [page]);

  const groups = useMemo(() => {
    const res: Record<string, AlumniMember[]> = {};
    alumni.forEach((m: any) => {
      const year = m.classYear || "Legacy";
      if (!res[year]) res[year] = [];
      res[year].push(m);
    });
    Object.keys(res).forEach((y) => {
      res[y].sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0));
    });
    return res;
  }, [alumni]);

  const sortedYears = useMemo(() => {
    return Object.keys(groups).sort((a, b) => {
      if (a === "Legacy") return 1;
      if (b === "Legacy") return -1;
      return parseInt(b, 10) - parseInt(a, 10);
    });
  }, [groups]);

  if (page?.content) {
    return <div dangerouslySetInnerHTML={{ __html: page.content }} />;
  }

  return (
    <div className="team-page alumni-page">
      <section className="page-hero">
        <div className="container">
          <span className="mono">Once OPCODE, Always OPCODE</span>
          <h1>Alumni</h1>
        </div>
      </section>

      {/* Founding Team Section */}
      <section className="section" style={{ paddingBottom: "2rem" }}>
        <div className="container">
          <div className="section-header" style={{ marginBottom: "2.5rem" }}>
            <h2>Founding Team</h2>
            <p>The ones who started it all in 2018.</p>
          </div>
          <div className="founding-photo" style={{ maxWidth: 800, margin: "0 auto", border: "1px solid rgba(253, 92, 17, 0.22)", overflow: "hidden" }}>
            <img 
              src="opcode founding team.jpg" 
              alt="OPCODE Founding Team" 
              loading="lazy" 
              style={{ width: "100%", height: "auto", display: "block" }} 
            />
          </div>
        </div>
      </section>

      {/* Alumni Archive Section */}
      <section className="section" style={{ paddingTop: "2rem" }}>
        <div className="container">
          <div className="section-header">
            <h2>The Archive</h2>
            <p>OPCODE names from previous batches, managed from the admin roster.</p>
          </div>

          {isLoading && <p className="mono">Loading alumni...</p>}
          {!isLoading && alumni.length === 0 && <p className="mono">No alumni listed yet.</p>}

          {sortedYears.map((year) => {
            const list = groups[year];
            return (
              <div key={year} className="team-tier-ref" style={{ marginBottom: "3rem" }}>
                <div className="tier-label">{year}</div>
                <div className="member-grid member-grid--lead">
                  {list.map((m) => (
                    <article key={m.id} className="member alumni-card">
                      <div className="member__photo">
                        {m.photoUrl ? <img src={m.photoUrl} alt={m.name} loading="lazy" /> : null}
                        <span>{initials(m.name)}</span>
                      </div>
                      <h3 className="member__name">{m.name}</h3>
                      <p className="alumni-card__desc" style={{ fontFamily: "'Share Tech Mono', monospace", fontSize: "0.68rem", letterSpacing: "0.12em", textTransform: "uppercase", color: "#c42d52", marginTop: "0.35rem" }}>
                        {m.role || "OPCODE Alumni"}
                      </p>
                    </article>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      </section>
    </div>
  );
}
